http.Get("/study/v1/me",[&store](const httplib::Request& req,httplib::Response& res) {
    if(!req.params.empty() || !req.body.empty()) {reply(res,400,{{"error","invalid_request"}});return;}
    const auto header=req.get_header_value("Authorization");
    if(req.get_header_value_count("Authorization")!=1 || header.compare(0,7,"Bearer ")!=0 ||
       !study_meta::credential_hex(header.substr(7),32)) {
        reply(res,401,{{"error","invalid_credential"}});return;
    }
    try {
        const auto profile=store.profile_by_hash(study_meta::account_hash(header.substr(7)));
        if(!profile){reply(res,401,{{"error","invalid_credential"}});return;}
        reply(res,200,study_meta::profile_json(*profile));
    }catch(const std::exception&) {reply(res,503,{{"error","profile_unavailable"}});}
});

std::optional<PublicProfile> profile_by_hash(const std::string& digest) {
    if(digest.size()!=64 || digest.find_first_not_of("0123456789abcdef")!=std::string::npos)
        throw std::invalid_argument("invalid credential hash");
    std::lock_guard<std::mutex> lock(mutex_);
    Statement q(db_.get(),"SELECT a.player_id,c.rp,c.xp,w.bp FROM account_keys a "
        "LEFT JOIN careers c ON c.player_id=a.player_id "
        "LEFT JOIN wallets w ON w.player_id=a.player_id WHERE a.token_hash=?1");
    q.text(1,digest);
    if(!q.next())return std::nullopt;
    const auto id=decimal(q.text_column(0));
    const auto rp=q.integer_column(1),xp=q.integer_column(2),bp=q.integer_column(3);
    if(id==0 || rp<0 || rp>kProgressLimit || xp<0 || xp>kProgressLimit || bp<0 || bp>kBalanceLimit)
        throw std::runtime_error("invalid account profile");
    return PublicProfile{id,static_cast<int>(rp),static_cast<int>(xp),static_cast<int>(bp)};
}

inline std::optional<PublicProfile> parse_profile(const std::string& body) {
  // Require a strict, flat object with exactly the four known fields.
  std::optional<Json> json = object(body, 4);
  if (!json) return std::nullopt;

  // Every field must be a non-negative integer; number() rejects the rest.
  std::optional<std::uint64_t> player_id = number(*json, "player_id");
  std::optional<std::uint64_t> rp = number(*json, "rp");
  std::optional<std::uint64_t> xp = number(*json, "xp");
  std::optional<std::uint64_t> bp = number(*json, "bp");
  if (!player_id || !rp || !xp || !bp) return std::nullopt;

  // player_id must be positive; int fields must fit before any cast.
  if (*player_id == 0) return std::nullopt;
  if (*rp > kMaxInt32 || *xp > kMaxInt32 || *bp > kMaxInt32) return std::nullopt;

  PublicProfile p;
  p.player_id = *player_id;  // preserve full 64-bit id unchanged
  p.rp = static_cast<int>(*rp);
  p.xp = static_cast<int>(*xp);
  p.bp = static_cast<int>(*bp);
  return p;
}

void reply(httplib::Response& res,int status,const study_meta::Json& body) {
    res.status=status;
    res.set_header("Cache-Control","no-store");
    res.set_content(body.dump(),"application/json");
}

